items.react:
import { Part, UI } from "@colibri-kit/ui/react";

export function Demo() {
  return (
    <UI kind="alert-dialog">
      <Part name="trigger" as="button">Delete article…</Part>
      <Part name="content" as="dialog">
        <Part name="title" as="h2">Are you sure?</Part>
        <Part name="description" as="p">This action cannot be undone.</Part>
        <div className="row">
          <Part name="close" as="button" data-ui-return="cancel" autoFocus>Cancel</Part>
          <Part name="close" as="button" data-ui-return="ok" data-variant="destructive">Delete</Part>
        </div>
      </Part>
    </UI>
  );
}

