const model = {
  "brand": "Northstar",
  "title": "Overview",
  "description": "Three projects are on track. One needs your review.",
  "pages": [
    {
      "id": "overview",
      "title": "Overview",
      "description": "Three projects are on track. One needs your review."
    },
    {
      "id": "records",
      "title": "Records",
      "description": "Project Atlas \u00b7 Active. Website refresh \u00b7 In review. Mobile release \u00b7 Planned."
    }
  ]
};

// Supply handlers for application actions; callbacks receive action/id or form/values.
