import { KnowledgeArticle } from "@colibri-kit/ui/react";
import "@colibri-kit/css";
import "@colibri-kit/css/applications";

const model = {
  "title": "Invite a teammate",
  "author": "Jordan Lee \u00b7 Updated November 2",
  "summary": "Add people to your workspace and choose their access.",
  "steps": [
    {
      "title": "Open Members",
      "text": "Choose Members from workspace settings."
    },
    {
      "title": "Send an invitation",
      "text": "Enter the email address and select a role."
    }
  ],
  "href": "dashboards/account.html?view=members",
  "linkLabel": "Open member settings"
};

// Supply handlers for application actions; callbacks receive action/id or form/values.
export function Example({ onAction, onSubmit }) {
  return <div className="colibri-application"><KnowledgeArticle model={model} onAction={onAction} onSubmit={onSubmit} /></div>;
}

